<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { useRouter } from 'vue-router'
import { profileApi } from '../api/profile'
const router=useRouter(); const loading=ref(true); const submitting=ref(false); const error=ref(''); const message=ref(''); const current=ref<any>(null)
const form=ref({investment_experience_years:0,max_loss_tolerance:10,investment_horizon_years:1,liquidity_need:'medium',investment_goal:'balanced',risk_willingness:20})
const levelText:Record<string,string>={C1:'C1 保守型',C2:'C2 稳健型',C3:'C3 平衡型',C4:'C4 成长型',C5:'C5 进取型'}
async function load(){try{current.value=(await profileApi.riskAssessment()).data.data;if(current.value) Object.assign(form.value,current.value.answers)}catch(e:any){error.value=e.response?.data?.detail||e.message}finally{loading.value=false}}
async function submit(){submitting.value=true;error.value='';message.value='';try{current.value=(await profileApi.submitRiskAssessment(form.value)).data.data;message.value='风险测评已提交，当前等级为 '+(levelText[current.value.risk_level]||current.value.risk_level)}catch(e:any){error.value=e.response?.data?.detail||e.message}finally{submitting.value=false}}
onMounted(load)
</script>
<template><section class="form-module"><div class="enterprise-page-actions"><button class="text-button" type="button" @click="router.push('/customer-center')">← 返回客户中心</button><button class="text-button" type="button" @click="router.push('/')">返回前台</button></div><div class="section-heading"><div><span class="eyebrow">RISK ASSESSMENT</span><h2>风险测评</h2><p>根据你的投资经验、风险承受能力和投资目标生成风险等级。</p></div></div><p v-if="error" class="error">{{error}}</p><p v-if="message" class="success">{{message}}</p><div v-if="loading" class="empty">正在读取测评状态…</div><template v-else><div v-if="current" class="profile-panel"><strong>当前等级：{{levelText[current.risk_level]||current.risk_level}}</strong><p>测评分数：{{current.score}} · 状态：{{current.status}}</p></div><form class="product-editor-grid" @submit.prevent="submit"><label>投资经验（年）<input v-model.number="form.investment_experience_years" type="number" min="0" max="80" required /></label><label>最大可接受亏损（%）<input v-model.number="form.max_loss_tolerance" type="number" min="0" max="100" required /></label><label>投资期限（年）<input v-model.number="form.investment_horizon_years" type="number" min="0" max="100" required /></label><label>风险承受意愿（%）<input v-model.number="form.risk_willingness" type="number" min="0" max="100" required /></label><label>流动性需求<select v-model="form.liquidity_need"><option value="high">高</option><option value="medium">中</option><option value="low">低</option></select></label><label>投资目标<select v-model="form.investment_goal"><option value="capital_preservation">资产保值</option><option value="income">稳定收益</option><option value="balanced">均衡配置</option><option value="growth">资产增长</option><option value="aggressive">高风险增值</option></select></label><label class="full"><button class="button" :disabled="submitting">{{submitting?'提交中…':'提交/更新测评'}}</button></label></form></template></section></template>